// Hand-written `@orpc/server` stub for the flowatlas fixture suite.
//
// Shaped like the real package in the ways the reading depends on. A builder's
// every link hands back another builder, and only `handler` ends one, so a
// reader that looked one call deep would fail here. `router` hands back what it
// was given, because an oRPC router is any object whose values are procedures.
// `implement` hands back something nothing here types, which is what a
// contract's implementer is in a clone nobody installed.
//
// It declares less than the library: no context inference, no event
// iterators, no plugins. It declares nothing of a different kind.

export interface Procedure {
  readonly '~orpc': true;
}

export interface HandlerOptions {
  input: any;
  context: any;
  errors: any;
}

export interface MiddlewareOptions {
  context: any;
  next(options?: { context?: unknown }): Promise<unknown>;
  errors: any;
}

export interface Builder {
  $context<C>(): Builder;
  input(schema: unknown): Builder;
  output(schema: unknown): Builder;
  use(middleware: (options: MiddlewareOptions) => unknown): Builder;
  errors(map: Record<string, { message?: string; status?: number; data?: unknown }>): Builder;
  route(route: { method?: string; path?: string; tags?: string[]; inputStructure?: 'compact' | 'detailed'; outputStructure?: 'compact' | 'detailed' }): Builder;
  prefix(prefix: string): Builder;
  router<T>(router: T): T;
  handler(fn: (options: HandlerOptions) => unknown): Procedure;
}

export declare const os: Builder;

export declare function implement<T>(contract: T): any;

export declare function lazy<T>(load: () => Promise<{ default: T }>): T;

export declare class ORPCError<TCode extends string = string> extends Error {
  constructor(code: TCode, options?: { message?: string; status?: number; data?: unknown });
  readonly code: TCode;
  readonly status: number;
}

export declare function call(procedure: unknown, input: unknown, options?: { context?: unknown }): Promise<any>;

export declare function createRouterClient<T>(router: T, options?: { context?: unknown }): any;
